SECTIONS = {}                                                                        # section name -> its catalog entry (folder, warning ...), filled by load_catalog


def load_catalog():
    with open(CATALOG, encoding='utf-8') as f:
        catalog = json.load(f)
    SECTIONS.update({s['name']: s for s in catalog['sections']})
    return catalog


def button_image(kind, layout, enabled):
    """ The picture for a button, from BUTTON_IMAGES below (drawn by dev/draw_icons.py, embedded by the sync).  None if it isn't there - the button shows its text instead """
    return BUTTON_IMAGES.get(f'btn_{kind}_{layout}{"" if enabled else "_off"}')


def set_button(window, state, key, enabled, visible=True):
    """ Enable/disable a button and swap in the matching picture for the current layout """
    state.enabled[key] = enabled
    kind, label = next((k, lab) for kk, k, lab in BUTTONS if kk == key)
    data = button_image(kind, state.layout, enabled)
    window[key].update(disabled=not enabled and data is None, visible=visible, image_data=data, text='' if data else label,     # a picture button stays enabled (tk stipples disabled images) - the event loop ignores it
                       button_color=(BG, BG) if data else playground_dark['BUTTON'])
    if visible:
        window[key].Widget.pack_configure(padx=BTN_PAD[state.layout][0], pady=BTN_PAD[state.layout][1])        # a re-shown button gets the current layout's spacing


def lay_out_buttons(window, state, layout):
    """ wide = icon + label side by side;  tall = icon above a short label (for narrow panes) """
    state.layout = layout
    for key, kind, label in BUTTONS:
        window[key].update(image_data=button_image(kind, layout, state.enabled.get(key, True)))
        if window[key].visible:                                                      # pack_configure would re-show a hidden button (Demo for an app with no demo)
            window[key].Widget.pack_configure(padx=BTN_PAD[layout][0], pady=BTN_PAD[layout][1])


def app_folder(app):
    """ the section's folder (catalog 'folder' - System Tray's is Tray), then the app's own sub-folder if it has one """
    section = SECTIONS.get(app['section'], {}).get('folder') or app['section']
    return os.path.join(ROOT, section, app['folder']) if app.get('folder') else os.path.join(ROOT, section)


def app_path(app):
    return os.path.join(app_folder(app), app['file']) if app.get('file') else ''


def installed(package):
    names = IMPORT_NAMES.get(package.lower(), (package.replace('-', '_'),))
    return any(importlib.util.find_spec(n) is not None for n in names)


def missing_packages(app):
    return [p for p in app.get('requires') or [] if not installed(p)]


def version_key(v):
    """ A version as something that compares right: 2.2.9 < 2.2.18, 6.3 == 6.3.0, 6.4rc1 < 6.4.  () when there's no number in it (same rule as Pip Refresh) """
    m = re.match(r'\s*v?(\d+(?:\.\d+)*)(.*)', v or '')
    if not m:
        return ()
    nums = [int(x) for x in m.group(1).split('.')]
    while len(nums) > 1 and nums[-1] == 0:
        nums.pop()
    return tuple(nums), 0 if m.group(2).strip(' .') else 1


def pip_only(app):
    """ An app that is its own pip package (psghotkey) - no file in the Playground """
    return bool(app.get('pip')) and not app.get('file')


def local_version(app):
    """ The version of the copy here: the app file's version line, or the installed package's version for a pip app.  None when it has none """
    if pip_only(app):
        try:
            return importlib.metadata.version(app['pip'])
        except importlib.metadata.PackageNotFoundError:
            return None
    try:
        with open(app_path(app), encoding='utf-8', errors='replace') as f:
            m = VERSION_RE.search(f.read(VERSION_BYTES))
    except OSError:
        return None
    return m.group(1) if m else None


def github_version(app):
    """ (GitHub's newest version, None) or (None, why not).  The app's file in this repo, or the setup.py of a pip app's own repo (its 'link').  Network - runs in a thread """
    repo = re.match(r'https://github\.com/([^/]+/[^/#?]+)', app.get('link') or '')
    if app.get('file'):
        url, pattern = f'{RAW}/{os.path.relpath(app_path(app), ROOT).replace(os.sep, "/")}', VERSION_RE
    elif repo:
        url, pattern = f'https://raw.githubusercontent.com/{repo.group(1)}/main/setup.py', SETUP_RE
    else:
        return None, 'no copy on GitHub'
    try:
        request = urllib.request.Request(url, headers={'User-Agent': f'{APP_NAME}/{VERSION}', 'Range': f'bytes=0-{VERSION_BYTES - 1}'})
        with urllib.request.urlopen(request, timeout=15) as res:
            text = res.read(VERSION_BYTES).decode('utf-8', 'replace')
    except urllib.error.HTTPError as e:
        return None, 'not on GitHub yet' if e.code == 404 else f'GitHub answered {e.code}'
    except Exception as e:
        return None, f'could not reach GitHub ({e.__class__.__name__})'
    m = pattern.search(text)
    return (m.group(1), None) if m else (None, 'no version line on GitHub')


def python_for(path):
    """pythonw for .pyw files on Windows (no console window), otherwise this interpreter"""
    exe = sys.executable
    if sys.platform == 'win32' and path.lower().endswith('.pyw'):
        pyw = os.path.join(os.path.dirname(exe), 'pythonw.exe')
        if os.path.isfile(pyw):
            return pyw
    return exe


def run_app(app, demo=False):
    path = app_path(app)
    if not os.path.isfile(path):
        return f'Not here yet: {os.path.relpath(path, ROOT)}'
    args = [python_for(path), path] + ([app['args_demo']] if demo and app.get('args_demo') else [])
    subprocess.Popen(args, cwd=app_folder(app))
    return f'Started {app["name"]}' + (' (demo)' if demo else '')


def open_folder(path):
    if sys.platform == 'win32':
        os.startfile(path)
    elif sys.platform == 'darwin':
        subprocess.Popen(['open', path])
    else:
        subprocess.Popen(['xdg-open', path])


def start_size(saved):
    """ The window's size: the one saved last time, else DEFAULT_SIZE - no bigger than the screen, no smaller than MIN_SIZE.  Never (None, None): a window
        left to size itself follows its contents - it came up as wide as the longest text and only 420 high, with the screenshot cut off """
    w, h = saved if isinstance(saved, (list, tuple)) and len(saved) == 2 and all(isinstance(v, int) for v in saved) else DEFAULT_SIZE
    screen_w, screen_h = sg.Window.get_screen_size()
    return max(MIN_SIZE[0], min(w, screen_w - 40)), max(MIN_SIZE[1], min(h, screen_h - 80))


