                       [sg.Text('Needs:', font=FONT_BOLD), sg.Multiline('', key=K_NEEDS, size=(40, 2), disabled=True, no_scrollbar=True, border_width=0, font=FONT,
                                                                        background_color=BG, expand_x=True)],
                       [sg.Button(label, key=key, image_data=button_image(kind, 'wide', True), button_color=(BG, BG) if button_image(kind, 'wide', True) else playground_dark['BUTTON'],
                                  mouseover_colors=(BG, BG), border_width=0, pad=BTN_PAD['wide'], bind_return_key=key == K_RUN) for key, kind, label in BUTTONS],
